func cmdCompare(args []string) int {
	if len(args) < 2 {
		fmt.Fprintln(os.Stderr, "Usage: mlpipe compare <pipeline1.yaml> <pipeline2.yaml> ...")
		return 1
	}

	type pipelineInfo struct {
		Name     string
		Pipeline *Pipeline
		IDs      []string
	}
	var pipelines []pipelineInfo
	idToPipeline := make(map[string]int)

	for i, file := range args {
		p, err := loadPipeline(file)
		if err != nil {
			fmt.Fprintln(os.Stderr, "error:", err)
			return 1
		}
		if errs := validatePipeline(p); len(errs) > 0 {
			for _, e := range errs {
				fmt.Fprintln(os.Stderr, e)
			}
			return 1
		}
		info := pipelineInfo{Name: p.Name, Pipeline: p}
		for _, combo := range parameterCombinations(p) {
			id := experimentID(combo)
			if prev, ok := idToPipeline[id]; ok {
				fmt.Fprintf(os.Stderr, "error: experiment ID collision: %s between pipelines %s and %s\n", id, pipelines[prev].Name, p.Name)
				return 1
			}
			idToPipeline[id] = i
			info.IDs = append(info.IDs, id)
		}
		pipelines = append(pipelines, info)
	}

	for _, info := range pipelines {
		matching := 0
		for _, id := range info.IDs {
			if experimentStateExists(id) {
				matching++
			}
		}
		if matching == 0 {
			fmt.Fprintf(os.Stderr, "error: pipeline %s has no matching experiments under .mlpipe/state\n", info.Name)
			return 1
		}
	}

	metricObjective := make(map[string]string)
	for i, info := range pipelines {
		pm := make(map[string]string)
		for _, stage := range info.Pipeline.Stages {
			for _, m := range stage.Metrics {
				if m.Objective != "minimize" && m.Objective != "maximize" {
					continue
				}
				if existing, ok := pm[m.Name]; ok && existing != m.Objective {
					fmt.Fprintf(os.Stderr, "error: conflicting objective for metric %s in pipeline %s\n", m.Name, info.Name)
					return 1
				}
				pm[m.Name] = m.Objective
			}
		}
		if i == 0 {
			metricObjective = pm
		} else {
			for k, v := range metricObjective {
				if v2, ok := pm[k]; !ok || v2 != v {
					delete(metricObjective, k)
				}
			}
		}
	}
	sharedMetrics := make([]string, 0, len(metricObjective))
	for k := range metricObjective {
		sharedMetrics = append(sharedMetrics, k)
	}
	sort.Strings(sharedMetrics)
	if len(sharedMetrics) == 0 {
		fmt.Fprintln(os.Stderr, "error: no shared objective metrics found across pipelines")
		return 1
	}

	included := []compareExperimentData{}
	for _, info := range pipelines {
		for _, id := range info.IDs {
			if !experimentStateExists(id) {
				continue
			}
			metrics := collectExperimentMetrics(info.Pipeline, id)
			allPresent := true
			for _, m := range sharedMetrics {
				if _, ok := metrics[m]; !ok {
					allPresent = false
					break
				}
			}
			if !allPresent {
				continue
			}
			included = append(included, compareExperimentData{ID: id, Pipeline: info.Name, Metrics: metrics})
		}
	}

	normalized := make([]map[string]float64, len(included))
	for i := range normalized {
		normalized[i] = make(map[string]float64)
	}
	for _, m := range sharedMetrics {
		min := math.Inf(1)
		max := math.Inf(-1)
		for _, exp := range included {
			v := exp.Metrics[m]
			if v < min {
				min = v
			}
			if v > max {
				max = v
			}
		}
		for i, exp := range included {
			var norm float64
			if max == min {
				norm = 0.5
			} else {
				norm = (exp.Metrics[m] - min) / (max - min)
			}
			if metricObjective[m] == "minimize" {
				norm = 1 - norm
			}
			normalized[i][m] = norm
		}
	}

	composite := make([]float64, len(included))
	for i := range included {
		sum := 0.0
		for _, m := range sharedMetrics {
			sum += normalized[i][m]
		}
		if len(sharedMetrics) > 0 {
			composite[i] = sum / float64(len(sharedMetrics))
		}
	}

	depth := make([]int, len(included))
	remaining := make([]int, len(included))
	for i := range remaining {
		remaining[i] = i
	}
	currentDepth := 0
	for len(remaining) > 0 {
		nonDom := []int{}
		for _, i := range remaining {
			dominated := false
			for _, j := range remaining {
				if i == j {
					continue
				}
				if dominates(normalized[j], normalized[i], sharedMetrics) {
					dominated = true
					break
				}
			}
			if !dominated {
				nonDom = append(nonDom, i)
			}
		}
		if len(nonDom) == 0 {
			for _, i := range remaining {
				depth[i] = currentDepth
			}
			break
		}
		for _, i := range nonDom {
			depth[i] = currentDepth
		}
		newRemaining := make([]int, 0, len(remaining)-len(nonDom))
		for _, i := range remaining {
			found := false
			for _, j := range nonDom {
				if i == j {
					found = true
					break
				}
			}
			if !found {
				newRemaining = append(newRemaining, i)
			}
		}
		remaining = newRemaining
		currentDepth++
	}

	order := make([]int, len(included))
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool {
		if composite[order[a]] != composite[order[b]] {
			return composite[order[a]] > composite[order[b]]
		}
		return included[order[a]].ID < included[order[b]].ID
	})
	rank := make([]int, len(included))
	currentRank := 0
	prevComposite := math.NaN()
	for _, idx := range order {
		if currentRank == 0 || composite[idx] != prevComposite {
			currentRank++
			prevComposite = composite[idx]
		}
		rank[idx] = currentRank
	}

	type experimentOut struct {
		ID              string             `json:"id"`
		Pipeline        string             `json:"pipeline"`
		Metrics         map[string]float64 `json:"metrics"`
		Normalized      map[string]float64 `json:"normalized"`
		CompositeScore  float64            `json:"composite_score"`
		Rank            int                `json:"rank"`
		IsParetoOptimal bool               `json:"is_pareto_optimal"`
		DominanceDepth  int                `json:"dominance_depth"`
	}
	experiments := []experimentOut{}
	for _, idx := range order {
		experiments = append(experiments, experimentOut{
			ID:              included[idx].ID,
			Pipeline:        included[idx].Pipeline,
			Metrics:         included[idx].Metrics,
			Normalized:      normalized[idx],
			CompositeScore:  composite[idx],
			Rank:            rank[idx],
			IsParetoOptimal: depth[idx] == 0,
			DominanceDepth:  depth[idx],
		})
	}

	paretoFrontier := []string{}
	for i, exp := range included {
		if depth[i] == 0 {
			paretoFrontier = append(paretoFrontier, exp.ID)
		}
	}
	sort.Strings(paretoFrontier)

	type correlationOut struct {
		Spearman *float64 `json:"spearman_rho"`
		Kendall  *float64 `json:"kendall_tau"`
		N        int      `json:"n"`
	}
	correlations := map[string]correlationOut{}
	for i := 0; i < len(sharedMetrics); i++ {
		for j := i + 1; j < len(sharedMetrics); j++ {
			rho, tau := computeCorrelations(included, sharedMetrics[i], sharedMetrics[j])
			correlations[sharedMetrics[i]+"_vs_"+sharedMetrics[j]] = correlationOut{Spearman: rho, Kendall: tau, N: len(included)}
		}
	}

	pipelineNames := []string{}
	for _, info := range pipelines {
		pipelineNames = append(pipelineNames, info.Name)
	}
	maxDepth := 0
	paretoCount := 0
	for i := range included {
		if depth[i] > maxDepth {
			maxDepth = depth[i]
		}
		if depth[i] == 0 {
			paretoCount++
		}
	}
	type bestExperiment struct {
		ID             string  `json:"id"`
		Pipeline       string  `json:"pipeline"`
		CompositeScore float64 `json:"composite_score"`
	}
	var best *bestExperiment
	if len(order) > 0 {
		idx := order[0]
		best = &bestExperiment{ID: included[idx].ID, Pipeline: included[idx].Pipeline, CompositeScore: composite[idx]}
	}
	summary := struct {
		Total          int            `json:"total_experiments"`
		ParetoCount    int            `json:"pareto_count"`
		MaxDominance   int            `json:"max_dominance_depth"`
		BestExperiment *bestExperiment `json:"best_experiment"`
	}{
		Total:          len(included),
		ParetoCount:    paretoCount,
		MaxDominance:   maxDepth,
		BestExperiment: best,
	}
	out := struct {
		Pipelines      []string                 `json:"pipelines"`
		SharedMetrics  []string                 `json:"shared_metrics"`
		Experiments    []experimentOut          `json:"experiments"`
		ParetoFrontier []string                 `json:"pareto_frontier"`
		Correlations   map[string]correlationOut `json:"correlations"`
		Summary        struct {
			Total          int            `json:"total_experiments"`
			ParetoCount    int            `json:"pareto_count"`
			MaxDominance   int            `json:"max_dominance_depth"`
			BestExperiment *bestExperiment `json:"best_experiment"`
		} `json:"summary"`
	}{
		Pipelines:      pipelineNames,
		SharedMetrics:  sharedMetrics,
		Experiments:    experiments,
		ParetoFrontier: paretoFrontier,
		Correlations:   correlations,
		Summary:        summary,
	}
	enc := json.NewEncoder(os.Stdout)
	enc.SetIndent("", "  ")
	if err := enc.Encode(out); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		return 1
	}
	return 0
}

func computeCorrelations(experiments []compareExperimentData, a, b string) (*float64, *float64) {
	n := len(experiments)
	if n < 3 {
		return nil, nil
	}
	valuesA := make([]float64, n)
	valuesB := make([]float64, n)
	for i, e := range experiments {
		valuesA[i] = e.Metrics[a]
		valuesB[i] = e.Metrics[b]
	}
	rho := spearmanRankCorrelation(valuesA, valuesB)
	r := round4(rho)
	tau := kendallTauB(valuesA, valuesB)
	if tau == nil {
		return &r, nil
	}
	t := round4(*tau)
	return &r, &t
}

func spearmanRankCorrelation(a, b []float64) float64 {
	n := len(a)
	rankA := fractionalRanks(a)
	rankB := fractionalRanks(b)
	sumD2 := 0.0
	for i := 0; i < n; i++ {
		d := rankA[i] - rankB[i]
		sumD2 += d * d
	}
	return 1 - 6*sumD2/(float64(n)*(float64(n)*float64(n)-1))
}

func fractionalRanks(values []float64) []float64 {
	n := len(values)
	type pair struct {
		val float64
		idx int
	}
	pairs := make([]pair, n)
	for i, v := range values {
		pairs[i] = pair{val: v, idx: i}
	}
	sort.SliceStable(pairs, func(i, j int) bool {
		return pairs[i].val < pairs[j].val
	})
	ranks := make([]float64, n)
	i := 0
	for i < n {
		j := i
		for j < n && pairs[j].val == pairs[i].val {
			j++
		}
		rank := float64(i+j+1) / 2.0
		for k := i; k < j; k++ {
			ranks[pairs[k].idx] = rank
		}
		i = j
	}
	return ranks
}

func kendallTauB(a, b []float64) *float64 {
	n := len(a)
	concordant, discordant, tiedFirst, tiedSecond, tiedBoth := 0, 0, 0, 0, 0
	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			da := a[i] - a[j]
			db := b[i] - b[j]
			aTied := da == 0
			bTied := db == 0
			if aTied && bTied {
				tiedBoth++
				continue
			}
			if aTied {
				tiedFirst++
				continue
			}
			if bTied {
				tiedSecond++
				continue
			}
			if (da > 0 && db > 0) || (da < 0 && db < 0) {
				concordant++
			} else {
				discordant++
			}
		}
	}
	denom := math.Sqrt(float64((concordant + discordant + tiedFirst) * (concordant + discordant + tiedSecond)))
	if denom == 0 {
		return nil
	}
	tau := float64(concordant-discordant) / denom
	return &tau
}

func round4(f float64) float64 {
	f = math.Round(f*10000) / 10000
	if f == 0 {
		f = 0
	}
	return f
}
EOF

